package com.adent.attendance.api; import com.adent.shared.security.CurrentUser; import com.adent.staff.repository.StaffRepository; import com.adent.shared.exception.NotFoundException; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/attendance") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class AttendanceController {private final CurrentUser current;private final JdbcTemplate jdbc;private final StaffRepository staff;public AttendanceController(CurrentUser c,JdbcTemplate j,StaffRepository s){current=c;jdbc=j;staff=s;}@GetMapping public List<Map<String,Object>> list(@RequestParam LocalDate from,@RequestParam LocalDate to){return jdbc.queryForList("select a.id,a.staff_id,s.first_names,s.last_names,a.record_date,a.check_in,a.check_out,a.status,a.notes from attendance_records a join staff s on s.id=a.staff_id where a.tenant_id=? and a.record_date between ? and ? order by a.record_date desc,s.last_names",current.tenantId(),from,to);}@PostMapping public Map<String,Object> save(@RequestBody Request r){staff.findByIdAndTenantId(r.staffId(),current.tenantId()).orElseThrow(()->new NotFoundException("Personal no encontrado"));UUID id=UUID.randomUUID();jdbc.update("insert into attendance_records(id,tenant_id,staff_id,record_date,check_in,check_out,status,notes) values(?,?,?,?,?,?,?,?) on conflict(tenant_id,staff_id,record_date) do update set check_in=excluded.check_in,check_out=excluded.check_out,status=excluded.status,notes=excluded.notes,updated_at=now()",id,current.tenantId(),r.staffId(),r.recordDate(),r.checkIn(),r.checkOut(),r.status(),r.notes());return Map.of("status","OK");} public record Request(UUID staffId,LocalDate recordDate,LocalTime checkIn,LocalTime checkOut,String status,String notes){} }
